css:
.kpi-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: 'Segoe UI', Arial, sans-serif;
  box-sizing: border-box;
  isolation: isolate;
}
.kpi-root * {
  box-sizing: border-box;
}
.kpi-title {
  position: absolute;
  left: 12px;
  right: 12px;
  top: 5px;
  text-align: center;
  font-weight: 700;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  z-index: 2;
}
.kpi-area {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  pointer-events: none;
  z-index: 0;
}
.kpi-content {
  position: absolute;
  left: 10px;
  right: 10px;
  top: 50%;
  transform: translateY(-35%);
  text-align: center;
  z-index: 2;
  pointer-events: none;
}
.kpi-value-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  white-space: nowrap;
}
.kpi-value {
  font-weight: 400;
  line-height: 1.12;
  white-space: nowrap;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi-icon {
  line-height: 1;
  flex: none;
}
.kpi-goal {
  font-weight: 650;
  line-height: 1.4;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kpi-date {
  font-size: 12px;
  margin-top: 4px;
  opacity: 0.8;
}
.kpi-empty {
  position: absolute;
  inset: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  line-height: 1.6;
  font-size: 14px;
}
.kpi-hit {
  position: absolute;
  z-index: 3;
  inset: 0;
  background: transparent;
  border: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  cursor: default;
}
.kpi-hit:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: -3px;
}
.kpi-warning {
  position: absolute;
  bottom: 3px;
  right: 5px;
  font-size: 10px;
  z-index: 4;
}
